import {world,liquid,input,ui,scenes} from 'judas';
export const properties={radial:{type:'boolean',default:false}};
export default class {
 constructor({properties}){this.props=properties;this.state={transferred:0};}
 start(){this.hud=ui.get('lab');if(this.hud){this.hud.modal=false;this.hud.get('title').text=this.props.radial?'RADIAL / CURVED EQUIPOTENTIAL':'RESERVOIR LAB / CONSERVED VOLUME';this.hud.get('hitmark').visible=false;}}
 fixedUpdate(){const main=world.entity(this.props.radial?'120':'20')?.liquid,storage=world.entity(this.props.radial?'121':'21')?.liquid;if(!main||!storage)return;if(input.pressed('drain'))this.state.transferred=main.transferTo(storage,.8);if(input.pressed('refill'))this.state.transferred=storage.transferTo(main,.8);
 if(!this.props.radial){const a=world.entity('30')?.liquid,b=world.entity('31')?.liquid,tank=world.entity('32')?.liquid;if(a&&b&&tank){if(input.pressed('fill_graph'))tank.transferTo(a,1.1);if(input.pressed('drain_graph')){a.transferTo(tank,Math.max(0,a.state.volume-.1));b.transferTo(tank,Math.max(0,b.state.volume-.1));}}}}
 uiUpdate(){if(!this.hud)return;if(input.pressed('pause')){this.hud.modal=!this.hud.modal;this.hud.get('pause').visible=this.hud.modal;input.pointerCapture=!this.hud.modal;}const owner=id=>{const e=world.entity(id);return e?.valid?e.liquid:null;};const main=owner(this.props.radial?'120':'20'),storage=owner(this.props.radial?'121':'21'),receiver=owner('22'),bucket=owner('200');const a=liquid.accounting('water');this.hud.get('score').text=`MAIN ${(1000*(main?.state.volume||0)).toFixed(2)} L   STORAGE ${(1000*(storage?.state.volume||0)).toFixed(2)} L   RECEIVER ${(1000*(receiver?.state.volume||0)).toFixed(2)} L`;this.hud.get('progress').text=`BUCKET ${(1000*(bucket?.state.volume||0)).toFixed(2)} L  ALL CONTAINERS ${(1000*a.containers).toFixed(2)} L  DETACHED ${(1000*a.detached).toFixed(2)} L  TOTAL ${(1000*a.total).toFixed(6)} L`;const graph=liquid.accounting('graph-water');this.hud.get('message').text=liquid.errors.length?liquid.errors[0].message:this.props.radial?'Q/E: transfer 800 L out/back. Surface uses real radial equipotentials.':`G: pickup/drop | P held: tilt/pour | wheel: carry height | F/H: spill fill/drain | saddle active ${liquid.connections.some(c=>c.active)} | graph ${(graph.total*1000).toFixed(1)} L`;this.state.total=a.total;this.state.error=a.error;}
 onUI(e){if(e.type==='back'||(e.type==='click'&&e.element==='resume')){this.hud.modal=false;this.hud.get('pause').visible=false;input.pointerCapture=true;}if(e.type==='click'&&e.element==='restart')scenes.reload();if(e.type==='click'&&e.element==='quit')ui.quit();}
}
